protected void cleanup()
{
    BatchJob                         batchJob;
    TransDateTime                    delDate = cleanupTaskSettings.getCleanupDateTime();
    boolean                          continueDelete;

    setPrefix("Batch job delete");

    while select batchJob
            where batchJob.OrigStartDateTime <= delDate &&
                  batchJob.OrigStartDateTime &&
                  batchJob.Status != BatchStatus::Hold  &&
                  batchJob.Status != BatchStatus::Waiting
    {
        setPrefix(strFmt("%1 - %2", batchJob.Caption, batchJob.RecId));
        batchJob.skipAosValidation(true);

        // a record that fails to delete does not stop the task
        continueDelete = true;

        try
        {
            continueDelete = this.deleteRecord(batchJob);
        }
        catch
        {
            exceptionTextFallThrough();
        }

        if (!continueDelete)
        {
            break;
        }
    }
}

public void estimate()
{
    BatchJob                         batchJob;
    TransDateTime                    delDate = cleanupTaskSettings.getCleanupDateTime();

    select count(RecId) from batchJob
        where batchJob.OrigStartDateTime <= delDate &&
              batchJob.OrigStartDateTime &&
              batchJob.Status != BatchStatus::Hold &&
              batchJob.Status != BatchStatus::Waiting;

    info(strFmt("BatchJob not Withhold count for %1 date: %2", delDate, batchJob.RecId));
}
